import { db } from './lib/db';
import { toggleNotifications } from './actions';

export default function Home() {
  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently: <strong>{db.notificationsEnabled ? 'ON' : 'OFF'}</strong></p>

      <form action={toggleNotifications}>
        <button type="submit">
          Toggle Notifications
        </button>
      </form>
    </main>
  );
}

