import { describe, it, expect, vi, beforeEach } from 'vitest';
import { toggleNotifications } from './actions';
import { db } from './lib/db';

// Mock revalidatePath
vi.mock('next/cache', () => ({
  revalidatePath: vi.fn(),
}));

import { revalidatePath } from 'next/cache';

describe('toggleNotifications', () => {
  beforeEach(() => {
    // Reset db state
    db.notificationsEnabled = false;
    vi.clearAllMocks();
  });

  it('toggles notification preference and revalidates path', async () => {
    // Initial state
    expect(db.notificationsEnabled).toBe(false);

    // Call action
    await toggleNotifications();

    // Check state updated
    expect(db.notificationsEnabled).toBe(true);

    // Check revalidatePath called
    expect(revalidatePath).toHaveBeenCalledWith('/');

    // Toggle back
    await toggleNotifications();
    expect(db.notificationsEnabled).toBe(false);
  });
});

